# ---------- MUC 6 ----------
P(('h2','6. 5 sai lầm thường gặp khi thiết kế văn phòng 70m2'))
P(('p','Năm lỗi dưới đây gặp ở hầu hết phương án doanh nghiệp tự lên. Điểm chung của cả năm: hậu quả đều quy được ra số chỗ ngồi hoặc số tiền phải sửa lại.'))
P(('table',
   ['Sai lầm','Vì sao hay mắc','Cái giá phải trả'],
   [['1. Bố trí quá nhiều phòng kín','Ai cũng muốn có phòng riêng, và trên bản vẽ trông rất ngăn nắp','Ba phòng kín lấy đi 8 – 10m² cho riêng phần tường, vách và hành lang dẫn vào — tương đương mất 4 – 5 chỗ ngồi'],
    ['2. Bóp lối đi để kê thêm bàn','Thêm được một bàn là thấy lợi ngay trên bản vẽ','Lối đi dưới 1,2m khiến người ngồi phía trong phải đứng dậy nhường đường mỗi lần có người đi qua, và không đạt chuẩn thoát hiểm'],
    ['3. Chọn nội thất sai tỷ lệ','Bàn lớn, tủ cao trông sang hơn trong ảnh','Bàn 1,6m × 0,8m thay cho bàn 1,2m × 0,6m làm mất 3 – 4 chỗ ngồi trên 70m² mà không thêm công năng nào'],
    ['4. Không quy hoạch điện, mạng từ đầu','Nghĩ rằng lắp sau cũng được','Phải đi dây nổi sau khi vào ở, hoặc đục lại sàn và vách vừa hoàn thiện — phát sinh cả chi phí lẫn thời gian ngừng làm việc'],
    ['5. Thiết kế vừa khít số người hiện tại','Ngân sách có hạn, chưa chắc năm sau tuyển thêm','Tăng 20% nhân sự là hết chỗ, phải cải tạo lại chỉ sau 1 – 2 năm — chi phí cải tạo thường cao hơn làm dư ngay từ đầu']]))
P(('p','Cách phòng đơn giản nhất cho lỗi thứ năm: khi lên phương án, cộng thêm 15 – 20% số chỗ ngồi so với nhân sự hiện tại, và chọn bàn mô-đun ghép nối được để phần dư đó không thành khoảng trống lãng phí.'))
P(('img','a70-24','5 sai lầm thường gặp khi thiết kế văn phòng 70m2 và hậu quả trên mặt bằng'))
P(('img','a70-09','Lối đi trong văn phòng cần tối thiểu 1,2m — bóp hẹp hơn là người ngồi trong phải đứng dậy nhường đường'))

# ---------- MUC 7 ----------
P(('h2','7. Chi phí thiết kế và thi công văn phòng 70m2'))
P(('p','Đây là chỗ doanh nghiệp dễ hiểu nhầm nhất. Phí thiết kế và chi phí thi công là hai khoản hoàn toàn khác nhau, chênh nhau hơn mười lần. Bảng dưới đây tách rõ hai khoản, theo khoảng giá thị trường Hà Nội và TP.HCM năm 2026.'))
P(('table',
   ['Hạng mục','Đơn giá thị trường','Thành tiền cho 70m²'],
   [['Phí thiết kế','150.000 – 400.000 đ/m²','10,5 – 28 triệu'],
    ['Thi công gói cơ bản','2,5 – 4 triệu/m²','175 – 280 triệu'],
    ['Thi công gói tiêu chuẩn','4 – 7 triệu/m²','280 – 490 triệu'],
    ['Thi công gói cao cấp','trên 7 triệu/m²','trên 490 triệu']]))
P(('note','Gói cơ bản: sơn, sàn, trần, hệ điện cơ bản, nội thất rời phổ thông. Gói tiêu chuẩn: thêm vách kính, tủ âm tường, hệ chiếu sáng thiết kế riêng, nội thất đặt sản xuất. Gói cao cấp: vật liệu nhập khẩu, hệ thống thông minh, gia công đặc thù. Đây là khoảng giá tham khảo — báo giá thực tế phụ thuộc hiện trạng mặt bằng và yêu cầu riêng.'))

P(('h3','7.1. Năm yếu tố quyết định chi phí thiết kế văn phòng 70m2'))
P(('ul',[
  '**Hiện trạng mặt bằng.** Mặt bằng thô phải làm lại toàn bộ hệ kỹ thuật; mặt bằng đã có trần, sàn, điều hòa thì tiết kiệm được một phần đáng kể.',
  '**Số phòng kín.** Mỗi phòng kín thêm chi phí vách, cửa, hệ điện và chiếu sáng riêng.',
  '**Chất lượng vật liệu nội thất.** Cùng một chiếc bàn, gỗ công nghiệp phủ melamine và gỗ tự nhiên chênh nhau 2 – 3 lần.',
  '**Mức độ phức tạp của hệ kỹ thuật.** Điện, mạng, điều hòa, phòng cháy — càng nhiều điểm chờ thì chi phí càng tăng.',
  '**Yêu cầu riêng theo ngành.** Khu trưng bày sản phẩm, phòng tư vấn cách âm, kho hồ sơ đều là hạng mục cộng thêm.']))

P(('h3','7.2. Tiết kiệm chi phí ở đâu mà văn phòng 70m2 vẫn chuyên nghiệp'))
P(('p','Nguyên tắc chung: **giữ tiền cho khu khách nhìn thấy, cắt ở khu nội bộ.** Lễ tân và phòng họp là hai nơi quyết định ấn tượng của đối tác — nên đầu tư đúng mức. Khu làm việc chung, pantry và kho có thể dùng vật liệu phổ thông mà không ai nhận ra sự khác biệt.'))
P(('ul',[
  '**Bỏ trần giật cấp nhiều lớp**, giữ trần phẳng hoặc để mộc — tiết kiệm 15 – 25 triệu cho 70m².',
  '**Dùng vách kính khung nhôm** thay vách thạch cao cách âm ở phòng họp — rẻ hơn, nhanh hơn, lại giữ được chỗ ngồi.',
  '**Chọn nội thất mô-đun có sẵn** thay đặt sản xuất riêng cho khu làm việc chung.',
  '**Doanh nghiệp thuê ngắn hạn dưới 3 năm** nên ưu tiên hạng mục tháo lắp mang đi được — bàn, tủ, vách di động — thay vì hạng mục xây cố định.']))

# ---------- MUC 8 ----------
P(('h2','8. Vì sao chọn Crystal Design TPL cho văn phòng 70m2'))
P(('p','Crystal Design TPL (thương hiệu Deco Crystal) có **hơn 25 năm kinh nghiệm** thiết kế, sản xuất và thi công nội thất trọn gói tại Việt Nam và khu vực Đông Nam Á. Với mặt bằng 70m², ba điểm sau là thứ ảnh hưởng trực tiếp đến kết quả doanh nghiệp nhận được:'))
P(('ul',[
  '**Nhà xưởng sản xuất 6.000m².** Nội thất do chính công ty sản xuất nên chủ động được tiến độ và điều chỉnh kích thước theo đúng mặt bằng thực tế — điều quan trọng với diện tích nhỏ, nơi lệch vài centimet là kê không vừa.',
  '**Đội ngũ chuyên gia kết hợp Việt Nam – Hàn Quốc**, nâng cao tiêu chuẩn thiết kế và thi công so với mặt bằng chung.',
  '**Khảo sát và thiết kế 3D miễn phí.** Doanh nghiệp nhìn thấy phương án bố trí và số chỗ ngồi thực tế trước khi quyết định ngân sách.']))
P(('img','a70-23','Khu vực lễ tân do Crystal Design TPL thiết kế và thi công — điểm chạm đầu tiên quyết định ấn tượng của khách'))

# ---------- MUC 9 ----------
P(('h2','9. Câu hỏi thường gặp khi thiết kế văn phòng 70m2'))

P(('h3','9.1. Chi phí thiết kế thi công văn phòng 70m2 khoảng bao nhiêu?'))
P(('p','Cần tách làm hai khoản. **Phí thiết kế** theo giá thị trường là 150.000 – 400.000đ/m², tương đương 10,5 – 28 triệu cho 70m². **Chi phí thi công** là khoản lớn hơn nhiều: 175 – 280 triệu với gói cơ bản, 280 – 490 triệu với gói tiêu chuẩn. Con số 20 – 35 triệu thường thấy trên mạng chỉ là phí thiết kế, không bao gồm thi công.'))

P(('h3','9.2. Thời gian thi công văn phòng 70m2 mất bao lâu?'))
P(('p','Khoảng **28 – 38 ngày** cho một văn phòng 70m² gói tiêu chuẩn, gồm: khảo sát 1 – 2 ngày · thiết kế và dựng 3D 7 – 10 ngày · hồ sơ kỹ thuật 3 – 5 ngày · sản xuất và thi công 15 – 20 ngày · nghiệm thu bàn giao 1 – 2 ngày. Đây là khoảng tham khảo theo tiến độ phổ biến của ngành; mốc chính xác phụ thuộc hiện trạng mặt bằng và số vòng duyệt bản vẽ.'))

P(('h3','9.3. Văn phòng 70m2 có làm được phòng giám đốc riêng không?'))
P(('p','Làm được. Một phòng giám đốc đủ dùng cần 8 – 12m², gồm bàn làm việc, tủ tài liệu và một bàn tiếp khách nhỏ 2 – 4 chỗ. Cái giá là khoảng 2 chỗ ngồi ở khu chung. Nếu muốn giữ cả phòng giám đốc lẫn phòng họp kín, mặt bằng 70m² thường chỉ còn 10 – 11 chỗ ngồi — xem lại tổ hợp C ở mục 2. Cách dung hòa phổ biến: làm phòng giám đốc vách kính có rèm, vừa riêng tư khi cần vừa không cắt vụn không gian.'))

P(('h3','9.4. Văn phòng 70m2 có nên thiết kế không gian mở không?'))
P(('p','Nên, nếu ưu tiên số chỗ ngồi. Không gian mở cho ra nhiều hơn 2 – 3 chỗ so với phương án chia phòng, và dễ đổi bố cục khi nhân sự thay đổi. Tuy nhiên vẫn nên giữ ít nhất một phòng họp vách kính để có chỗ tiếp khách và gọi điện quan trọng. Kèm theo đó là trần tiêu âm hoặc tấm tiêu âm treo — ở mật độ trên 12 người trong 70m², tiếng ồn là vấn đề có thật.'))

# ---------- KET BAI ----------
P(('p','Tóm lại, một mặt bằng 70m² bố trí được 10 – 15 chỗ ngồi tùy vào việc doanh nghiệp giữ hay bỏ các phòng kín, và riêng hình dạng mặt bằng đã làm con số này chênh nhau khoảng 2 chỗ. Về ngân sách, phí thiết kế rơi vào 10,5 – 28 triệu, còn chi phí thi công là 175 – 490 triệu tùy gói vật liệu; toàn bộ quá trình từ khảo sát đến bàn giao mất khoảng 28 – 38 ngày. Điều quyết định không phải là 70m² rộng hay hẹp, mà là doanh nghiệp chọn bỏ đúng thứ ngay từ bản vẽ đầu tiên — **thiết kế văn phòng 70m2** làm tốt là khi mỗi mét vuông bỏ đi đều đổi lại được một thứ doanh nghiệp thực sự cần. Crystal Design TPL khảo sát mặt bằng và dựng phương án 3D miễn phí, để doanh nghiệp thấy rõ mặt bằng của mình bố trí được bao nhiêu chỗ ngồi trước khi quyết định ngân sách.'))

P(('box_tacgia','Đặng Trường Minh — Giám đốc Thiết kế, Crystal Design TPL','Hơn 25 năm trong ngành thiết kế và thi công nội thất văn phòng. Trực tiếp phụ trách các phương án bố trí mặt bằng cho doanh nghiệp vừa và nhỏ tại Hà Nội và TP.HCM.'))

